# Instalar o pipeline HyperKB

O HyperKB é um CLI em Python (só biblioteca padrão no núcleo) que guarda bases em `/home/box/hyperkb/<bot>/<tema>/` com `sources/`, `text/`, `parts/`, `notes/`, `sources.json`, `index.db` e `manual.md`. Se `/home/box/hyperkb/bin/kb` já existir, não reescreva: reuse.

## Passos
1. Instale as dependências uma vez (pule o que já existir):
   - apt: `poppler-utils ocrmypdf tesseract-ocr tesseract-ocr-por tesseract-ocr-eng ffmpeg`
   - pip (`--user`): `yt-dlp faster-whisper trafilatura`
   - Opcional para destilação por motor externo: `codex` (OpenAI Codex CLI) e/ou `claude` (Claude Code), já logados. Sem eles, use `--engine grok`.
2. Crie `/home/box/hyperkb/bin/kb` com o código abaixo, exatamente, e `chmod +x`.
3. Crie `/home/box/hyperkb/prompts/distill-part.md` e `/home/box/hyperkb/prompts/distill-merge.md` com os textos abaixo, exatamente.
4. Teste numa base descartável `teste/demo`: ingira um PDF pequeno e uma página da web pública, rode `kb index`, 3 buscas reais, `kb parts`, reingira o mesmo PDF (deve sair SKIP), e apague a pasta `/home/box/hyperkb/teste`. Se o usuário tiver codex ou claude logado, rode um `kb distill teste/demo --engine <motor>` e `kb check teste/demo` antes de apagar.
5. Se as flags do `codex exec` ou do `claude -p` tiverem mudado (confira com `--help`), ajuste só a função `run_engine`.

## `/home/box/hyperkb/bin/kb`

````python
#!/usr/bin/env python3
"""kb - shared knowledge-base CLI (deterministic; LLMs only in `distill` via external CLIs)."""
import argparse, datetime, glob, hashlib, html, json, os, re, shutil, sqlite3, subprocess, sys, tempfile, unicodedata
from collections import Counter

ROOT = os.environ.get("HYPERKB_ROOT", "/home/box/hyperkb")
PROMPTS = os.path.join(ROOT, "prompts")
RESERVED = {"bin", "prompts"}
CHUNK_WORDS, CHUNK_OVERLAP, PART_WORDS = 800, 100, 15000
MARK_RE = re.compile(r"^\[(p\. \d+|\d{1,2}:\d{2}(?::\d{2})?)\]$")
os.environ["PATH"] = os.path.expanduser("~/.local/bin") + os.pathsep + os.environ.get("PATH", "")

STOP = set("""a o e é de da do das dos em no na nos nas um uma uns umas para pra por com sem que se ser são foi era
como mais mas ou ao aos à às isso isto esse essa este esta esses essas aquele aquela ele ela eles elas eu tu nós
vocês você seu sua seus suas meu minha nosso nossa qual quais quem onde quando porque porquê pois já não sim muito
muita muitos muitas tem têm ter há também só entre sobre até depois antes cada todo toda todos todas mesmo outra outro
the of and to in is it for on with as at by an be this that are was or from what which who how why when where do does
can you your my we they their there these those not but have has had will would should could about into than then them
its our out if so no yes all any some
fazer faz fazem usar uso qual quais seria pode posso devo deve sobre existe""".split())


def die(msg, code=1):
    print(f"ERRO: {msg}", file=sys.stderr); sys.exit(code)


def slugify(s, maxlen=60):
    s = unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode().lower()
    s = re.sub(r"[^a-z0-9]+", "-", s).strip("-")
    return (s[:maxlen].strip("-")) or "x"


def fold(s):
    return unicodedata.normalize("NFKD", s).encode("ascii", "ignore").decode().lower()


def base_dir(spec, create=False):
    parts = spec.strip("/").split("/")
    if len(parts) != 2: die("base deve ser <bot>/<tema>")
    bot, tema = slugify(parts[0]), slugify(parts[1])
    if bot in RESERVED: die(f"nome de bot reservado: {bot}")
    d = os.path.join(ROOT, bot, tema)
    if create:
        for sub in ("sources", "text", "parts", "notes"): os.makedirs(os.path.join(d, sub), exist_ok=True)
    elif not os.path.isdir(d): die(f"base não existe: {bot}/{tema}")
    return d, f"{bot}/{tema}"


def load_manifest(d):
    p = os.path.join(d, "sources.json")
    if os.path.exists(p):
        with open(p) as f: return json.load(f)
    return {"sources": [], "failures": []}


def save_manifest(d, m):
    p = os.path.join(d, "sources.json")
    with open(p + ".tmp", "w") as f: json.dump(m, f, ensure_ascii=False, indent=2)
    os.replace(p + ".tmp", p)


def sha256_file(p):
    h = hashlib.sha256()
    with open(p, "rb") as f:
        for b in iter(lambda: f.read(1 << 20), b""): h.update(b)
    return h.hexdigest()


def run(cmd, timeout=None, **kw):
    return subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, **kw)


def have(cmd): return shutil.which(cmd) is not None


def unique_slug(d, base):
    s, i = base, 2
    while glob.glob(os.path.join(d, "text", s + ".txt")) or glob.glob(os.path.join(d, "sources", s + ".*")):
        s = f"{base}-{i}"; i += 1
    return s


def write_text(d, slug, title, typ, origin, body, extra=None):
    hdr = [f"# {title}", f"Tipo: {typ}", f"Origem: {origin}"]
    for k, v in (extra or {}).items():
        if v: hdr.append(f"{k}: {v}")
    with open(os.path.join(d, "text", slug + ".txt"), "w") as f:
        f.write("\n".join(hdr) + "\n---\n\n" + body.strip() + "\n")
    return len(body.split())


def wc(s): return len(s.split())


def fmt_ts(sec):
    sec = int(sec); h, r = divmod(sec, 3600); m, s = divmod(r, 60)
    return f"{h}:{m:02d}:{s:02d}" if h else f"{m:02d}:{s:02d}"


# ---------------- PDF ----------------
def pdf_pages(path):
    r = run(["pdftotext", "-layout", path, "-"])
    if r.returncode != 0: raise RuntimeError("pdftotext falhou: " + r.stderr.strip()[:200])
    pages = r.stdout.split("\f")
    if pages and not pages[-1].strip(): pages = pages[:-1]
    return pages


def clean_page(t):
    lines = [re.sub(r"[ \t]+", " ", l).strip() for l in t.splitlines()]
    out, blank = [], False
    for l in lines:
        if not l:
            if not blank and out: out.append("")
            blank = True
        else: out.append(l); blank = False
    return "\n".join(out).strip()


def near_empty(pages):
    n = max(1, len(pages)); return sum(wc(p) for p in pages) < 10 * n


def ocr_pdf(path, tmp):
    if have("ocrmypdf"):
        out = os.path.join(tmp, "ocr.pdf")
        r = run(["ocrmypdf", "--force-ocr", "-l", "por+eng", "-q", path, out], timeout=3600)
        if r.returncode == 0: return pdf_pages(out), "ocrmypdf"
    if have("tesseract") and have("pdftoppm"):
        run(["pdftoppm", "-r", "300", "-png", path, os.path.join(tmp, "pg")], timeout=3600)
        pages = []
        for img in sorted(glob.glob(os.path.join(tmp, "pg*.png"))):
            r = run(["tesseract", img, "-", "-l", "por+eng"], timeout=600)
            pages.append(r.stdout)
        if pages: return pages, "tesseract"
    raise RuntimeError("PDF sem texto e OCR indisponível (ocrmypdf/tesseract)")


def pdf_title(path, fallback):
    r = run(["pdfinfo", path])
    m = re.search(r"^Title:\s*(.+)$", r.stdout or "", re.M)
    return m.group(1).strip() if m and m.group(1).strip() else fallback


def ingest_pdf(d, m, path):
    h = sha256_file(path)
    if any(s.get("sha256") == h for s in m["sources"]): return "skip", "mesmo hash"
    with tempfile.TemporaryDirectory() as tmp:
        pages, method = pdf_pages(path), "pdftotext"
        if near_empty(pages): pages, method = ocr_pdf(path, tmp)
    if near_empty(pages): raise RuntimeError("texto vazio mesmo após OCR")
    fname = os.path.splitext(os.path.basename(path))[0]
    title = pdf_title(path, fname)
    slug = unique_slug(d, slugify(fname))
    shutil.copy2(path, os.path.join(d, "sources", slug + ".pdf"))
    body = "\n\n".join(f"[p. {i}]\n{clean_page(p)}" for i, p in enumerate(pages, 1) if p.strip())
    n = write_text(d, slug, title, "pdf", os.path.abspath(path), body, {"Páginas": str(len(pages)), "Extração": method})
    m["sources"].append(dict(slug=slug, title=title, type="pdf", origin=os.path.abspath(path), sha256=h, words=n,
                             method=method, pages=len(pages), ingested_at=now()))
    return "ok", f"{n} palavras ({method}, {len(pages)} p.)"


def ingest_textfile(d, m, path):
    h = sha256_file(path)
    if any(s.get("sha256") == h for s in m["sources"]): return "skip", "mesmo hash"
    ext = os.path.splitext(path)[1].lower()
    raw = open(path, encoding="utf-8", errors="replace").read()
    fname = os.path.splitext(os.path.basename(path))[0]
    title, typ = fname, "texto"
    if ext in (".vtt", ".srt"):
        body, typ = vtt_to_text(raw), "legenda"
    elif ext in (".html", ".htm"):
        body, t = extract_html(raw, None); title, typ = t or fname, "html"
    else:
        body = raw
    if not body.strip(): raise RuntimeError("arquivo sem texto")
    slug = unique_slug(d, slugify(fname))
    shutil.copy2(path, os.path.join(d, "sources", slug + ext))
    n = write_text(d, slug, title, typ, os.path.abspath(path), body)
    m["sources"].append(dict(slug=slug, title=title, type=typ, origin=os.path.abspath(path), sha256=h, words=n, ingested_at=now()))
    return "ok", f"{n} palavras ({typ})"


# ---------------- YouTube ----------------
YT_RE = re.compile(r"(youtube\.com/(watch|shorts/|live/|embed/)|youtu\.be/)", re.I)


def ts_to_sec(t):
    p = t.replace(",", ".").split(":")
    p = [float(x) for x in p]
    while len(p) < 3: p.insert(0, 0.0)
    return p[0] * 3600 + p[1] * 60 + p[2]


def vtt_to_text(raw, group_sec=30):
    """Parse VTT/SRT (incl. YouTube rolling auto-captions) into deduped text with [mm:ss] markers."""
    cues, cur_t, buf = [], None, []
    tre = re.compile(r"(\d{1,2}:)?\d{1,2}:\d{2}[.,]\d{3}\s*-->\s*")
    for line in raw.splitlines() + [""]:
        if tre.search(line):
            if cur_t is not None and buf: cues.append((cur_t, buf))
            cur_t, buf = ts_to_sec(line.split("-->")[0].strip()), []
        elif not line.strip():
            if cur_t is not None and buf: cues.append((cur_t, buf))
            cur_t, buf = None, []
        elif cur_t is not None:
            buf.append(line)
    words_out, recent = [], []  # list of (sec, line)
    for t, lines in cues:
        for l in lines:
            l = re.sub(r"<[^>]+>", "", l); l = html.unescape(l).replace("\u200b", "")
            l = re.sub(r"\[(música|musica|aplausos|risos|music|applause|laughter)\]", " ", l, flags=re.I)
            l = re.sub(r"\s+", " ", l).strip()
            if not l or l in recent or re.fullmatch(r"\[[^\]]*\]", l): continue
            # remove overlap with previous line (rolling captions)
            if recent:
                prev = recent[-1].split(); cw = l.split()
                for k in range(min(len(prev), len(cw)), 0, -1):
                    if prev[-k:] == cw[:k]: cw = cw[k:]; break
                if not cw: recent.append(l); continue
                l2 = " ".join(cw)
            else: l2 = l
            recent = (recent + [l])[-4:]
            words_out.append((t, l2))
    paras, start, acc = [], None, []
    for t, l in words_out:
        if start is None: start = t
        if t - start >= group_sec and acc:
            paras.append(f"[{fmt_ts(start)}] " + " ".join(acc)); start, acc = t, []
        acc.append(l)
    if acc: paras.append(f"[{fmt_ts(start)}] " + " ".join(acc))
    return "\n\n".join(paras)


LANG_RE = re.compile(r"^(pt|en)(-[A-Za-z]{2,4})?(-orig)?$")


def choose_sub(info):
    """Pick ONE original (non-translated) pt/en subtitle track. Returns (code, is_auto)."""
    lang = (info.get("language") or "").split("-")[0].lower()
    manual = [k for k in (info.get("subtitles") or {}) if LANG_RE.match(k)]
    auto_all = list((info.get("automatic_captions") or {}).keys())
    orig = [k for k in auto_all if k.endswith("-orig")]
    olang = lang or (orig[0][:-5].split("-")[0] if orig else "")
    def rank(k):
        b = k.split("-")[0]
        return (0 if b == olang else 1, 0 if b == "pt" else 1 if b == "en" else 2, len(k))
    # 1) manual track in the video's own language (manual tracks in other languages are usually translations)
    same = [k for k in manual if k.split("-")[0] == olang]
    if same: return sorted(same, key=len)[0], False
    # 2) auto captions of the original language only (translations look like 'pt-en-US' or differ from video language)
    cand = [k for k in orig if LANG_RE.match(k) and (not olang or k.split("-")[0] == olang)] or \
           [k for k in auto_all if LANG_RE.match(k) and k.split("-")[0] == olang and k.count("-") <= 1]
    if cand: return sorted(cand, key=lambda k: (0 if k.endswith("-orig") else 1, len(k)))[0], True
    # 3) any pt/en manual track
    if manual: return sorted(manual, key=rank)[0], False
    return None, False


def ingest_youtube(d, m, url):
    if any(s.get("origin") == url for s in m["sources"]): return "skip", "mesma URL"
    ytdlp = [sys.executable, "-m", "yt_dlp"]
    if run(ytdlp + ["--version"]).returncode != 0:
        if not have("yt-dlp"): raise RuntimeError("yt-dlp não instalado")
        ytdlp = ["yt-dlp"]
    with tempfile.TemporaryDirectory() as tmp:
        r = run(ytdlp + ["-J", "--skip-download", "--no-playlist", url], timeout=300)
        if r.returncode != 0 or not r.stdout.strip():
            raise RuntimeError("yt-dlp falhou: " + (r.stderr.strip().splitlines() or ["?"])[-1][:200])
        info = json.loads(r.stdout)
        info_p = os.path.join(tmp, "v.info.json")
        with open(info_p, "w") as f: json.dump({k: info.get(k) for k in ("id", "title", "channel", "uploader", "duration",
                  "language", "upload_date", "webpage_url", "description")}, f, ensure_ascii=False, indent=1)
        vid = info.get("id") or slugify(url)
        if any(s.get("video_id") == vid for s in m["sources"]): return "skip", "mesmo vídeo"
        title, channel = info.get("title") or vid, info.get("channel") or info.get("uploader") or ""
        code, is_auto = choose_sub(info)
        lang = (info.get("language") or (code or "")).split("-")[0]
        body, method, srcfile, suberr = "", "", None, ""
        if code:
            # --sub-langs narrowed to ONE original track (pt.*/en.* would pull dozens of
            # auto-translated tracks and trigger HTTP 429)
            for attempt in range(3):
                r = run(ytdlp + ["--write-auto-subs", "--write-subs", "--sub-langs", "^" + re.escape(code) + "$", "--sub-format", "vtt",
                                 "--skip-download", "--no-playlist", "-o", os.path.join(tmp, "v.%(ext)s"), url], timeout=600)
                subs = glob.glob(os.path.join(tmp, "v.*.vtt"))
                if subs: break
                suberr = (r.stderr.strip().splitlines() or ["?"])[-1][:160]
                if "429" not in suberr: break
                import time; time.sleep(10 * (attempt + 1))
            if subs:
                sub = subs[0]
                body = vtt_to_text(open(sub, encoding="utf-8", errors="replace").read())
                method = ("legendas-auto:" if is_auto else "legendas:") + code; srcfile = sub
        if wc(body) < 20:
            try:
                body, method, srcfile = whisper_transcribe(ytdlp, url, tmp, lang)
            except RuntimeError as e:
                raise RuntimeError(f"{e}" + (f" (legendas: {suberr})" if suberr else ""))
        slug = unique_slug(d, slugify(title))
        if srcfile: shutil.copy2(srcfile, os.path.join(d, "sources", slug + os.path.splitext(srcfile)[1]))
        shutil.copy2(info_p, os.path.join(d, "sources", slug + ".info.json"))
    h = hashlib.sha256(body.encode()).hexdigest()
    if any(s.get("sha256") == h for s in m["sources"]): return "skip", "mesmo hash"
    n = write_text(d, slug, title, "youtube", url, body, {"Canal": channel, "Duração": fmt_ts(info.get("duration") or 0), "Transcrição": method})
    m["sources"].append(dict(slug=slug, title=title, channel=channel, type="youtube", origin=url, video_id=vid, sha256=h,
                             words=n, method=method, ingested_at=now()))
    return "ok", f"{n} palavras ({method}) — \"{title}\" / {channel}"


def whisper_transcribe(ytdlp, url, tmp, lang):
    try:
        from faster_whisper import WhisperModel
    except Exception:
        raise RuntimeError("sem legendas e faster-whisper indisponível")
    r = run(ytdlp + ["-f", "bestaudio/best", "--no-playlist", "-o", os.path.join(tmp, "audio.%(ext)s"), url], timeout=3600)
    aud = [f for f in glob.glob(os.path.join(tmp, "audio.*")) if not f.endswith(".part")]
    if not aud: raise RuntimeError("sem legendas e falha ao baixar áudio: " + r.stderr.strip()[-200:])
    model = WhisperModel("small", device="cpu", compute_type="int8")
    segs, _ = model.transcribe(aud[0], language=lang or None, vad_filter=True)
    paras, start, acc = [], None, []
    for s in segs:
        if start is None: start = s.start
        if s.start - start >= 30 and acc:
            paras.append(f"[{fmt_ts(start)}] " + " ".join(acc)); start, acc = s.start, []
        acc.append(s.text.strip())
    if acc: paras.append(f"[{fmt_ts(start)}] " + " ".join(acc))
    body = "\n\n".join(paras)
    if wc(body) < 5: raise RuntimeError("transcrição whisper vazia")
    return body, "whisper-small-int8", aud[0]


# ---------------- Web ----------------
def extract_html(raw, url):
    import trafilatura
    txt = trafilatura.extract(raw, url=url, include_comments=False, include_tables=True, favor_precision=True) or ""
    meta = trafilatura.extract_metadata(raw, default_url=url)
    title = meta.title if meta and meta.title else None
    return txt, title


def ingest_web(d, m, url):
    if any(s.get("origin") == url for s in m["sources"]): return "skip", "mesma URL"
    try:
        import trafilatura
    except Exception:
        raise RuntimeError("trafilatura não instalado")
    raw = trafilatura.fetch_url(url)
    if not raw:
        import urllib.request
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0 (X11; Linux x86_64) kb/1.0"})
            raw = urllib.request.urlopen(req, timeout=60).read().decode("utf-8", "replace")
        except Exception as e:
            raise RuntimeError(f"download bloqueado/falhou: {e}"[:200])
    body, title = extract_html(raw, url)
    if wc(body) < 30: raise RuntimeError("texto principal não extraído (página bloqueada ou vazia)")
    h = hashlib.sha256(raw.encode("utf-8", "replace")).hexdigest()
    if any(s.get("sha256") == h for s in m["sources"]): return "skip", "mesmo hash"
    title = title or url
    slug = unique_slug(d, slugify(title))
    with open(os.path.join(d, "sources", slug + ".html"), "w") as f: f.write(raw)
    n = write_text(d, slug, title, "web", url, body)
    m["sources"].append(dict(slug=slug, title=title, type="web", origin=url, sha256=h, words=n, ingested_at=now()))
    return "ok", f"{n} palavras (web) — \"{title}\""


def now(): return datetime.datetime.now().astimezone().isoformat(timespec="seconds")


def cmd_ingest(a):
    d, base = base_dir(a.base, create=True)
    m = load_manifest(d)
    ok = skip = fail = 0
    for item in a.items:
        try:
            if re.match(r"https?://", item):
                st, info = (ingest_youtube if YT_RE.search(item) else ingest_web)(d, m, item)
            elif os.path.isfile(item):
                st, info = (ingest_pdf if item.lower().endswith(".pdf") else ingest_textfile)(d, m, item)
            else:
                raise RuntimeError("arquivo não encontrado")
        except Exception as e:
            st, info = "fail", str(e).replace("\n", " ")[:240]
            m["failures"].append(dict(origin=item, reason=info, at=now()))
        save_manifest(d, m)
        ok += st == "ok"; skip += st == "skip"; fail += st == "fail"
        tag = {"ok": "OK  ", "skip": "SKIP", "fail": "FAIL"}[st]
        print(f"  {tag} {item[:90]} — {info}")
    total = sum(s.get("words", 0) for s in m["sources"])
    print(f"[{base}] ok={ok} pulados={skip} falhas={fail} | base: {len(m['sources'])} fontes, {total} palavras")
    if ok: print(f"  -> rode: kb index {base}")
    return 1 if fail and not ok and not skip else 0


# ---------------- Index ----------------
def read_textfile(p):
    raw = open(p, encoding="utf-8").read()
    head, _, body = raw.partition("\n---\n")
    title = head.splitlines()[0].lstrip("# ").strip() if head else os.path.basename(p)
    return title, head, body


def chunk_body(body):
    toks = body.split()
    # markers: "[p." "12]" (split by whitespace) or "[mm:ss]"
    words2, locs2, cur = [], [], ""
    i = 0
    while i < len(toks):
        t = toks[i]
        if t == "[p." and i + 1 < len(toks) and re.fullmatch(r"\d+\]", toks[i + 1]):
            cur = "p. " + toks[i + 1][:-1]; words2.append(f"[{cur}]"); locs2.append(cur); i += 2; continue
        mm = re.fullmatch(r"\[(\d{1,2}:\d{2}(?::\d{2})?)\]", t)
        if mm: cur = mm.group(1)
        words2.append(t); locs2.append(cur); i += 1
    chunks, step, i = [], CHUNK_WORDS - CHUNK_OVERLAP, 0
    while i < len(words2):
        seg = words2[i:i + CHUNK_WORDS]; sl = [l for l in locs2[i:i + CHUNK_WORDS] if l]
        # carry location from before chunk start
        if not sl or locs2[i] == "":
            prev = next((l for l in reversed(locs2[:i]) if l), "")
            if prev: sl = [prev] + sl
        chunks.append((" ".join(seg), loc_range(sl)))
        if i + CHUNK_WORDS >= len(words2): break
        i += step
    return chunks


def loc_range(sl):
    if not sl: return ""
    a, b = sl[0], sl[-1]
    if a == b: return a
    if a.startswith("p. ") and b.startswith("p. "): return f"p. {a[3:]}-{b[3:]}"
    return f"{a}-{b}"


def cmd_index(a):
    d, base = base_dir(a.base)
    files = sorted(glob.glob(os.path.join(d, "text", "*.txt")))
    if not files: die(f"nenhum texto em {base}; rode kb ingest antes")
    p = os.path.join(d, "index.db"); tmpp = p + ".tmp"
    if os.path.exists(tmpp): os.remove(tmpp)
    con = sqlite3.connect(tmpp)
    con.execute("CREATE VIRTUAL TABLE chunks USING fts5(text, title, source UNINDEXED, loc UNINDEXED, seq UNINDEXED, "
                "tokenize='unicode61 remove_diacritics 2')")
    n = 0
    for f in files:
        title, _, body = read_textfile(f)
        slug = os.path.splitext(os.path.basename(f))[0]
        for j, (txt, loc) in enumerate(chunk_body(body)):
            con.execute("INSERT INTO chunks(text,title,source,loc,seq) VALUES (?,?,?,?,?)", (txt, title, slug, loc, j)); n += 1
    con.execute("CREATE TABLE meta(k TEXT PRIMARY KEY, v TEXT)")
    con.execute("INSERT INTO meta VALUES ('built_at', ?), ('chunks', ?)", (now(), str(n)))
    con.commit(); con.close(); os.replace(tmpp, p)
    print(f"[{base}] index.db reconstruído: {len(files)} fontes, {n} chunks (~{CHUNK_WORDS} palavras, overlap {CHUNK_OVERLAP})")


# ---------------- Search ----------------
def query_terms(q):
    toks = re.findall(r"\w+", q.lower(), re.U)
    keep = [t for t in toks if len(t) > 2 and t not in STOP and fold(t) not in STOP]
    if not keep: keep = [t for t in toks if len(t) > 1] or toks
    seen, out = set(), []
    for t in keep:
        if fold(t) not in seen: seen.add(fold(t)); out.append(t)
    return out


def fts_query(terms):
    """OR of quoted tokens; tokens >= 5 chars become prefix queries (plural 's' dropped) to catch variants."""
    out = []
    for t in terms:
        t = t.replace('"', '""')
        if len(t) >= 5:
            out.append('"' + (t[:-1] if t.endswith("s") else t) + '"*')
        else:
            out.append('"' + t + '"')
    return " OR ".join(out)


def do_search(d, q, k):
    p = os.path.join(d, "index.db")
    if not os.path.exists(p): die("index.db ausente; rode kb index")
    terms = query_terms(q)
    if not terms: return terms, []
    con = sqlite3.connect(p)
    rows = con.execute("SELECT title, source, loc, text, bm25(chunks, 1.0, 0.5) AS s FROM chunks WHERE chunks MATCH ? "
                       "ORDER BY s LIMIT ?", (fts_query(terms), k)).fetchall()
    con.close()
    return terms, rows


def snippet(text, terms, n=1200):
    if len(text) <= n: return text
    ft = fold(text); fts = [fold(t) for t in terms]
    occ = [(m.start(), t) for t in fts for m in re.finditer(re.escape(t), ft)]
    start = 0
    if occ:
        best = max(occ, key=lambda o: (len({t for p, t in occ if o[0] - 150 <= p < o[0] - 150 + n}), -o[0]))
        start = max(0, best[0] - 150)
    if start + n > len(text): start = max(0, len(text) - n)
    if start: start = text.find(" ", start) + 1
    s = text[start:start + n]
    return ("… " if start else "") + s + (" …" if start + n < len(text) else "")


def cmd_search(a):
    d, base = base_dir(a.base)
    terms, rows = do_search(d, a.query, a.k)
    print(f"[{base}] busca: {' OR '.join(terms)} -> {len(rows)} resultado(s)")
    for i, (title, src, loc, text, s) in enumerate(rows, 1):
        print(f"\n=== #{i} | {title} | {loc or '-'} | bm25={-s:.2f}")
        print(snippet(text, terms))
    return 0 if rows else 2


# ---------------- List ----------------
def cmd_list(a):
    rows = []
    for d in sorted(glob.glob(os.path.join(ROOT, "*", "*"))):
        bot = os.path.basename(os.path.dirname(d))
        if bot in RESERVED or not os.path.isdir(d): continue
        if not (os.path.exists(os.path.join(d, "sources.json")) or os.path.isdir(os.path.join(d, "text"))): continue
        m = load_manifest(d); ch = "-"
        ip = os.path.join(d, "index.db")
        if os.path.exists(ip):
            try:
                con = sqlite3.connect(ip); ch = con.execute("SELECT count(*) FROM chunks").fetchone()[0]; con.close()
            except Exception: ch = "?"
        man = "sim" if os.path.exists(os.path.join(d, "manual.md")) else "não"
        rows.append(f"  {bot}/{os.path.basename(d)}  fontes={len(m['sources'])}  chunks={ch}  manual={man}")
    print(f"{len(rows)} base(s) em {ROOT}"); print("\n".join(rows))


# ---------------- Parts ----------------
def make_parts(d):
    files = sorted(glob.glob(os.path.join(d, "text", "*.txt")))
    if not files: die("nenhum texto; rode kb ingest")
    for f in glob.glob(os.path.join(d, "parts", "part-*.md")): os.remove(f)
    parts, cur, cw = [], [], 0
    for f in files:
        title, head, body = read_textfile(f)
        header = head.strip() + "\n"
        blocks = [b for b in re.split(r"\n\s*\n", body) if b.strip()]
        cur.append("\n" + header + "\n"); cw += wc(header)
        for b in blocks:
            if cw + wc(b) > PART_WORDS and cw > wc(header) + 50:
                parts.append("\n".join(cur)); cur = [f"\n# {title} (continuação)\n"]; cw = 0
            cur.append(b + "\n"); cw += wc(b)
    if cur: parts.append("\n".join(cur))
    paths = []
    for i, txt in enumerate(parts, 1):
        p = os.path.join(d, "parts", f"part-{i}.md")
        with open(p, "w") as fh: fh.write(txt.strip() + "\n")
        paths.append(p)
    return paths


def cmd_parts(a):
    d, base = base_dir(a.base)
    paths = make_parts(d)
    sizes = [wc(open(p).read()) for p in paths]
    print(f"[{base}] {len(paths)} parte(s) em parts/ (palavras: {', '.join(map(str, sizes))})")


# ---------------- Distill ----------------
def strip_fences(s):
    s = s.strip()
    mm = re.fullmatch(r"```(?:markdown|md)?\s*\n(.*)\n```", s, re.S)
    return mm.group(1).strip() if mm else s


def run_engine(engine, prompt, out_path, logdir, label):
    os.makedirs(logdir, exist_ok=True)
    log = os.path.join(logdir, f"{label}.{engine}.log")
    with tempfile.TemporaryDirectory() as wd:
        if engine == "codex":
            tmp_out = os.path.join(wd, "last.md")
            cmd = ["codex", "exec", "--skip-git-repo-check", "--sandbox", "read-only", "--ephemeral", "--color", "never",
                   "-C", wd, "-o", tmp_out, "-"]
            r = subprocess.run(cmd, input=prompt, capture_output=True, text=True, timeout=3600, cwd=wd)
            out = open(tmp_out).read() if os.path.exists(tmp_out) else ""
            if wc(out) < 20: out = r.stdout  # fallback: codex also prints the final message on stdout
        else:
            cmd = ["claude", "-p", "--tools", "Read,Grep,Glob", "--allowedTools", "Read,Grep,Glob",
                   "--permission-mode", "dontAsk", "--no-session-persistence", "--output-format", "text"]
            r = subprocess.run(cmd, input=prompt, capture_output=True, text=True, timeout=3600, cwd=wd)
            out = r.stdout
    with open(log, "w") as f: f.write(f"$ {' '.join(cmd)}\nexit={r.returncode}\n--- stdout ---\n{r.stdout[-20000:]}\n--- stderr ---\n{r.stderr[-20000:]}\n")
    out = strip_fences(out or "")
    if r.returncode != 0 or wc(out) < 20:
        raise RuntimeError(f"{engine} falhou em {label} (exit={r.returncode}); log: {log}")
    with open(out_path, "w") as f: f.write(out + "\n")
    return wc(out)


def cmd_distill(a):
    d, base = base_dir(a.base)
    parts = sorted(glob.glob(os.path.join(d, "parts", "part-*.md")), key=lambda p: int(re.findall(r"\d+", os.path.basename(p))[0]))
    if a.engine == "grok" or not parts or a.force: parts = make_parts(d)
    if a.engine == "grok":
        print(f"[{base}] engine=grok: {len(parts)} parte(s) prontas para o orquestrador destilar:")
        for p in parts: print(f"  {p}  -> notes/{os.path.basename(p)}")
        print(f"  prompts: {PROMPTS}/distill-part.md, {PROMPTS}/distill-merge.md (BASE={base}); manual: {d}/manual.md")
        return 0
    if not have(a.engine): die(f"{a.engine} não encontrado no PATH")
    pp, mp = os.path.join(PROMPTS, "distill-part.md"), os.path.join(PROMPTS, "distill-merge.md")
    part_prompt, merge_prompt = open(pp).read(), open(mp).read().replace("{BASE}", base)
    extra = f"\n\n## Instruções adicionais\n{a.extra.strip()}\n" if a.extra else ""
    logdir = os.path.join(d, "notes", ".logs")
    done = skipped = 0
    for p in parts:
        name = os.path.basename(p); outp = os.path.join(d, "notes", name)
        if os.path.exists(outp) and os.path.getsize(outp) > 0 and not a.force:
            skipped += 1; print(f"  {name}: notas já existem (pulado)"); continue
        content = open(p).read()
        prompt = f"{part_prompt}{extra}\n\n---\n# CONTEÚDO DA PARTE ({name})\n\n{content}"
        n = run_engine(a.engine, prompt, outp, logdir, name[:-3]); done += 1
        print(f"  {name}: notas geradas ({n} palavras)", flush=True)
    notes = sorted(glob.glob(os.path.join(d, "notes", "part-*.md")), key=lambda p: int(re.findall(r"\d+", os.path.basename(p))[0]))
    allnotes = "\n\n".join(f"<!-- {os.path.basename(n)} -->\n" + open(n).read() for n in notes)
    prompt = f"{merge_prompt}{extra}\n\n---\n# NOTAS DE TODAS AS PARTES ({len(notes)})\n\n{allnotes}"
    man = os.path.join(d, "manual.md")
    if (not a.force and not a.extra and done == 0 and os.path.exists(man) and os.path.getsize(man) > 0
            and all(os.path.getmtime(man) >= os.path.getmtime(x) for x in notes)):
        print(f"[{base}] distill ({a.engine}): partes puladas={skipped}; manual.md já atualizado (use --force para refazer)")
        return 0
    n = run_engine(a.engine, prompt, man, logdir, "merge")
    print(f"[{base}] distill ({a.engine}): partes geradas={done} puladas={skipped}; manual.md {n} palavras -> {man}")
    print(f"  -> rode: kb check {base}")


# ---------------- Check ----------------
CITE_RE = re.compile(r"\(Fonte:|\[p\.|\bp\.\s*\d+|\b\d{1,2}:\d{2}\b", re.I)
STD_SECTIONS = "principios centrais frameworks passo regras decisao vocabulario erros comuns onde autor discorda senso comum como consultar base".split()


def cmd_check(a):
    d, base = base_dir(a.base)
    man = os.path.join(d, "manual.md"); errs = []
    if not os.path.exists(man): die(f"manual.md ausente em {base}")
    txt = open(man).read(); n = wc(txt)
    if n == 0: errs.append("manual.md vazio")
    if n > 2600: errs.append(f"manual.md tem {n} palavras (> ~2500)")
    secs, cur = [], None
    for line in txt.splitlines():
        if re.match(r"^##\s+(?!#)", line): cur = [line[2:].strip(), []]; secs.append(cur)
        elif cur: cur[1].append(line)
    if not secs: errs.append("nenhuma seção ## encontrada")
    for title, body in secs:
        b = "\n".join(body)
        if "como consultar a base" in fold(title): continue
        if not CITE_RE.search(b): errs.append(f"seção '## {title}' sem citação de fonte")
    cons = [s for s in secs if "como consultar a base" in fold(s[0])]
    if not cons: errs.append("seção 'Como consultar a base' ausente")
    elif "kb search" not in "\n".join(cons[0][1]): errs.append("seção 'Como consultar a base' não contém 'kb search'")
    # test searches from headings (all levels), excluding standard section words
    heads = " ".join(re.sub(r"^#+\s*", "", l) for l in txt.splitlines() if l.startswith("#"))
    def cand(s):
        return [w for w in re.findall(r"\w+", s.lower()) if len(w) > 3 and not w.isdigit() and fold(w) not in STOP
                and fold(w) not in STD_SECTIONS and w not in STOP and fold(w) not in ("manual", "fonte", "parte")]
    hc = Counter(cand(heads)); bc = Counter(cand(re.sub(r"\(Fonte:[^)]*\)", "", txt)))
    ranked = sorted(hc, key=lambda w: (-hc[w], -bc[w])) + [w for w, _ in bc.most_common(50) if w not in hc]
    tests = []
    for w in ranked:
        if fold(w) not in {fold(t) for t in tests}: tests.append(w)
        if len(tests) == 3: break
    res = []
    if not os.path.exists(os.path.join(d, "index.db")): errs.append("index.db ausente")
    else:
        for t in tests:
            _, rows = do_search(d, t, 5); res.append(f"{t}={len(rows)}")
            if not rows: errs.append(f"busca de teste '{t}' sem resultados")
        if len(tests) < 3: errs.append("não foi possível extrair 3 termos de teste do manual")
    print(f"[{base}] manual.md: {n} palavras, {len(secs)} seções; buscas de teste: {', '.join(res) or '-'}")
    if errs:
        print("CHECK FALHOU:"); [print(f"  - {e}") for e in errs]; return 1
    print("CHECK OK"); return 0


def main():
    ap = argparse.ArgumentParser(prog="kb", description="Base de conhecimento compartilhada (bases em %s/<bot>/<tema>/)" % ROOT)
    sp = ap.add_subparsers(dest="cmd", required=True)
    p = sp.add_parser("ingest", help="ingere PDFs, arquivos, YouTube e URLs"); p.add_argument("base"); p.add_argument("items", nargs="+"); p.set_defaults(f=cmd_ingest)
    p = sp.add_parser("index", help="reconstrói index.db (FTS5)"); p.add_argument("base"); p.set_defaults(f=cmd_index)
    p = sp.add_parser("search", help="busca BM25"); p.add_argument("base"); p.add_argument("query"); p.add_argument("-k", type=int, default=5); p.set_defaults(f=cmd_search)
    p = sp.add_parser("list", help="lista bases"); p.set_defaults(f=cmd_list)
    p = sp.add_parser("parts", help="gera parts/part-N.md (~15k palavras)"); p.add_argument("base"); p.set_defaults(f=cmd_parts)
    p = sp.add_parser("distill", help="destila partes em notas e manual.md"); p.add_argument("base")
    p.add_argument("--engine", choices=["grok", "codex", "claude"], required=True); p.add_argument("--force", action="store_true")
    p.add_argument("--extra", default=""); p.set_defaults(f=cmd_distill)
    p = sp.add_parser("check", help="valida manual.md"); p.add_argument("base"); p.set_defaults(f=cmd_check)
    a = ap.parse_args()
    try:
        sys.exit(a.f(a) or 0)
    except subprocess.TimeoutExpired as e: die(f"timeout: {e.cmd[0] if e.cmd else ''}")
    except RuntimeError as e: die(str(e))


if __name__ == "__main__":
    main()
